BEGIN;
CREATE TABLE IF NOT EXISTS outclass_platform.assessment_banks(course_id uuid PRIMARY KEY REFERENCES outclass_platform.courses(id),author_id uuid NOT NULL,keys jsonb NOT NULL CHECK(octet_length(keys::text)<=300000));
CREATE TABLE IF NOT EXISTS outclass_platform.course_attempts(id uuid PRIMARY KEY,course_id uuid NOT NULL REFERENCES outclass_platform.courses(id),user_id uuid NOT NULL,item_id text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS course_attempt_owner ON outclass_platform.course_attempts(course_id,user_id,item_id);
ALTER TABLE outclass_platform.assessment_banks ENABLE ROW LEVEL SECURITY;
ALTER TABLE outclass_platform.assessment_banks FORCE ROW LEVEL SECURITY;
ALTER TABLE outclass_platform.course_attempts ENABLE ROW LEVEL SECURITY;
ALTER TABLE outclass_platform.course_attempts FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS bank_read ON outclass_platform.assessment_banks;
CREATE POLICY bank_read ON outclass_platform.assessment_banks FOR SELECT TO outclass_api USING(author_id=nullif(current_setting('outclass.actor_id',true),'')::uuid OR (course_id=nullif(current_setting('outclass.grading_course',true),'')::uuid AND EXISTS(SELECT 1 FROM outclass_platform.enrollments e WHERE e.course_id=assessment_banks.course_id AND e.user_id=nullif(current_setting('outclass.actor_id',true),'')::uuid)));
DROP POLICY IF EXISTS bank_insert ON outclass_platform.assessment_banks;
CREATE POLICY bank_insert ON outclass_platform.assessment_banks FOR INSERT TO outclass_api WITH CHECK(author_id=nullif(current_setting('outclass.actor_id',true),'')::uuid AND EXISTS(SELECT 1 FROM outclass_platform.courses c WHERE c.id=course_id AND c.author_id=assessment_banks.author_id));
DROP POLICY IF EXISTS attempt_read ON outclass_platform.course_attempts;
CREATE POLICY attempt_read ON outclass_platform.course_attempts FOR SELECT TO outclass_api USING(user_id=nullif(current_setting('outclass.actor_id',true),'')::uuid);
DROP POLICY IF EXISTS attempt_insert ON outclass_platform.course_attempts;
CREATE POLICY attempt_insert ON outclass_platform.course_attempts FOR INSERT TO outclass_api WITH CHECK(user_id=nullif(current_setting('outclass.actor_id',true),'')::uuid AND EXISTS(SELECT 1 FROM outclass_platform.enrollments e WHERE e.course_id=course_attempts.course_id AND e.user_id=course_attempts.user_id) OR (user_id=nullif(current_setting('outclass.actor_id',true),'')::uuid AND EXISTS(SELECT 1 FROM outclass_platform.courses c WHERE c.id=course_id AND c.author_id=course_attempts.user_id)));
REVOKE ALL ON outclass_platform.assessment_banks,outclass_platform.course_attempts FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT ON outclass_platform.assessment_banks,outclass_platform.course_attempts TO outclass_api;
COMMIT;
